# ===========================================================================
# Pure, import-safe accessor / reconciliation helpers.
# ===========================================================================
MAIN_TABLES = GROUP1_TABLES + GROUP2_TABLES


def all_tables():
    """Return the six main tables in canonical order (Tables 1-6)."""
    return list(MAIN_TABLES)


def all_main_rows():
    """Return every main row (94) in table order."""
    out = []
    for tbl in MAIN_TABLES:
        out.extend(tbl["rows"])
    return out


def all_layer1_rows():
    """Return every Layer-1 row (94) in table order."""
    out = []
    for tbl in LAYER1_TABLES:
        out.extend(tbl["rows"])
    return out


def all_layer2_rows():
    """Return every Layer-2 row (94) in table order."""
    out = []
    for tbl in LAYER2_TABLES:
        out.extend(tbl["rows"])
    return out


def iter_evidence_rows():
    """Yield all 282 evidence rows as (layer, table_id, row) triples."""
    for tbl in MAIN_TABLES:
        for row in tbl["rows"]:
            yield ("main", tbl["id"], row)
    for tbl in LAYER1_TABLES:
        for row in tbl["rows"]:
            yield ("l1", tbl["id"], row)
    for tbl in LAYER2_TABLES:
        for row in tbl["rows"]:
            yield ("l2", tbl["id"], row)


def _count_tokens(text):
    c = Counter()
    for flag in FLAG_VOCABULARY:
        n = text.count(flag)
        if n:
            c[flag] += n
    return c


def count_flags():
    """Count audit-flag tokens across the annotation corpus and return a dict.

    The corpus is: every main-row and Layer-2-row ``notes`` field (the row
    bands), the five legend descriptions (one of each flag is defined in the
    "Notes flags" entry), and every Coverage & Explicit-Absence Register entry
    (27 ``[ABSENT]`` tokens). This reconciles to ``FLAG_COUNTS``.
    """
    total = Counter()
    for tbl in MAIN_TABLES:
        for row in tbl["rows"]:
            total += _count_tokens(row.get("notes", ""))
    for tbl in LAYER2_TABLES:
        for row in tbl["rows"]:
            total += _count_tokens(row.get("notes", ""))
    for _label, text in LEGEND:
        total += _count_tokens(text)
    for sub in COVERAGE_REGISTER:
        for entry in sub["entries"]:
            blob = " ".join(str(v) for v in entry.values())
            total += _count_tokens(blob)
    return {flag: total.get(flag, 0) for flag in FLAG_VOCABULARY}


def reconcile():
    """Assert every structural, vocabulary, and flag invariant holds.

    Returns a dict of the computed aggregates on success; raises
    ``AssertionError`` on the first violated invariant.
    """
    core = sum(t["row_count"] for t in GROUP1_TABLES)
    indirect = sum(t["row_count"] for t in GROUP2_TABLES)
    assert core == CORE_MAIN_ROW_COUNT, (core, CORE_MAIN_ROW_COUNT)
    assert indirect == INDIRECT_MAIN_ROW_COUNT, indirect
    main_total = core + indirect
    assert main_total == MAIN_ROW_COUNT, main_total
    assert len(all_main_rows()) == MAIN_ROW_COUNT
    assert len(all_layer1_rows()) == MAIN_ROW_COUNT
    assert len(all_layer2_rows()) == MAIN_ROW_COUNT

    n_objects = (len(GROUP1_TABLES) + len(GROUP2_TABLES) +
                 len(LAYER1_TABLES) + len(LAYER2_TABLES))
    assert n_objects == DATA_OBJECT_COUNT, n_objects

    evidence = sum(1 for _ in iter_evidence_rows())
    assert evidence == EVIDENCE_ROW_COUNT, evidence

    for main_t, l1_t, l2_t in zip(MAIN_TABLES, LAYER1_TABLES, LAYER2_TABLES):
        nums = sorted(r["num"] for r in main_t["rows"])
        assert nums == list(range(1, main_t["row_count"] + 1)), main_t["id"]
        assert sorted(r["ref"] for r in l1_t["rows"]) == nums, l1_t["id"]
        assert sorted(r["ref"] for r in l2_t["rows"]) == nums, l2_t["id"]

    for row in all_main_rows():
        if "role" in row:
            assert row["role"] in ROLE_VOCABULARY, row["role"]
    for row in all_layer1_rows():
        assert row["dependency_type"] in DEPENDENCY_TYPE_VOCABULARY, \
            row["dependency_type"]

    for row in all_layer2_rows():
        assert row["chain_depth"] == row["full_dependency_chain"].count(
            "\u2192"), row["ref"]

    for row in all_main_rows():
        n = len(row["code_snippet"].split("\n"))
        assert 5 <= n <= 10, (row["file_path"], row["lines"], n)

    flags = count_flags()
    assert flags == FLAG_COUNTS, flags

    assert len(NEW_SERVICE_LOCATION_ROWS) == 12
    assert len(NEW_SERVICE_LOCATION_MAP) == 12

    assert len(COVERAGE_REGISTER) == COVERAGE_SUBREGISTER_COUNT
    n_cov = sum(len(s["entries"]) for s in COVERAGE_REGISTER)
    assert n_cov == COVERAGE_ENTRY_COUNT, n_cov

    return {
        "core_main_rows": core,
        "indirect_main_rows": indirect,
        "main_rows": main_total,
        "evidence_rows": evidence,
        "data_objects": n_objects,
        "flags": flags,
        "coverage_entries": n_cov,
        "new_service_location_rows": len(NEW_SERVICE_LOCATION_ROWS),
    }


